// BACKEND DUMMY andon untuk tablet. State di memori global Node-RED (hilang saat Node-RED restart).
// ponytail: data dummy dalam kode. Ganti ke database/API asli kalau sudah ada.
const STATIONS = [
  ['MA-1-LH', 'Main Assy-1-LH'], ['MA-1-RH', 'Main Assy-1-RH'], ['MA-3-LH', 'Main Assy-3-LH'],
  ['MA-3-RH', 'Main Assy-3-RH'], ['MA-5-LH', 'Main Assy-5-LH'], ['MA-5-RH', 'Main Assy-5-RH'],
  ['MA-6-LH', 'Main Assy-6-LH'], ['MA-7-RH', 'Main Assy-7-RH'], ['MA-8-LH', 'Main Assy-8-LH'],
  ['MA-8-RH', 'Main Assy-8-RH'], ['MA-9-RH', 'Main Assy-9-RH'], ['MA-10-LH', 'Main Assy-10-LH'],
  ['MA-11-LH', 'Main Assy-11-LH'], ['MA-11-RH', 'Main Assy-11-RH'], ['MA-12-LH', 'Main Assy-12-LH'],
  ['MA-13-RH', 'Main Assy-13-RH'], ['MA-14-LH', 'Main Assy-14-LH'], ['MA-15-RH', 'Main Assy-15-RH'],
  ['MA-16-LH', 'Main Assy-16-LH']
].map(([code, name]) => ({ code, name }));

const CATALOG = [
  { key: 'quality', name: 'Quality', reasons: ['Part NG / reject', 'Dimensi di luar toleransi', 'Cacat visual', 'Torque tidak sesuai'], planned: [] },
  { key: 'logistic', name: 'Logistic', reasons: ['Part habis', 'Part salah kirim', 'Part terlambat', 'Trolley kosong'], planned: [] },
  // planned = downtime terencana: TIDAK memengaruhi efisiensi (dikeluarkan dari waktu yang dihitung)
  { key: 'equipment', name: 'Equipment', reasons: ['Mesin berhenti', 'Tool rusak', 'Sensor error', 'Tekanan angin turun', 'Preventive maintenance'], planned: ['Preventive maintenance'] },
  { key: 'process', name: 'Process', reasons: ['Operator kurang', 'Cycle time terlalu lama', 'Instruksi kerja tidak jelas', 'Setting ulang proses', 'Istirahat', 'Briefing / 5S', 'Ganti model (changeover)', 'Finish production'], planned: ['Istirahat', 'Briefing / 5S', 'Ganti model (changeover)', 'Finish production'] }
];

const ACCOUNTS = [
  { email: 'operator1@dummy.local', password: 'operator1', name: 'Operator Satu' },
  { email: 'operator2@dummy.local', password: 'operator2', name: 'Operator Dua' }
];

const path = '/andon/' + msg.req.params.action;
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const reply = (code, payload) => { msg.statusCode = code; msg.payload = payload; return [msg, null]; };

if (path === '/andon/stations') return reply(200, STATIONS);

if (path === '/andon/login') {
  const ok = typeof body.email === 'string' && typeof body.password === 'string';
  const acc = ok && ACCOUNTS.find(a => a.email === body.email.trim().toLowerCase() && a.password === body.password);
  if (!acc) return reply(401, { message: 'Incorrect email or password.' });
  // ponytail: token acak seadanya (dummy). Ganti JWT/sesi asli saat login sungguhan.
  const token = Date.now().toString(36) + Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);
  const tokens = global.get('andonTokens') || {};
  tokens[token] = { email: acc.email, name: acc.name };
  global.set('andonTokens', tokens);
  // sesi operator -> tabel "Duty Worker" di dashboard. Login baru di station yang sama menutup sesi lama.
  const station = STATIONS.some(s => s.code === body.station) ? body.station : '-';
  const t = Date.now();
  const sessions = global.get('andonSessions') || [];
  sessions.forEach(x => { if (!x.end && station !== '-' && x.station === station) x.end = t; });
  sessions.push({ token, name: acc.name, station, start: t, end: null });
  global.set('andonSessions', sessions.slice(-60));
  return reply(200, { token, name: acc.name });
}

// semua di bawah ini wajib login
const bearer = String(msg.req.headers.authorization || '').replace(/^Bearer /, '');
const user = (global.get('andonTokens') || {})[bearer];
if (!user) return reply(401, { message: 'Unauthorized' });

if (path === '/andon/catalog') return reply(200, CATALOG);

if (path === '/andon/logout') {
  const t = Date.now();
  const sessions = global.get('andonSessions') || [];
  sessions.forEach(x => { if (x.token === bearer && !x.end) x.end = t; });
  global.set('andonSessions', sessions);
  const tokens = global.get('andonTokens') || {};
  delete tokens[bearer];
  global.set('andonTokens', tokens);
  return reply(200, { ok: true });
}

const station = String(path === '/andon/state' ? (msg.req.query.station || '') : (body.station || ''));
if (!STATIONS.some(s => s.code === station)) return reply(400, { message: 'Station tidak dikenal' });

const now = Date.now();
const events = (global.get('andonEvents') || []).filter(e => !e.end || now - e.start < 48 * 3600e3);
const active = events.find(e => !e.end && e.station === station);

if (path === '/andon/start') {
  const cat = CATALOG.find(c => c.key === body.category);
  if (!cat || !cat.reasons.includes(body.reason)) return reply(400, { message: 'Kategori atau alasan tidak valid' });
  if (active) return reply(409, { message: 'Andon masih aktif di station ini. Stop dulu.' });
  events.push({ station, category: cat.key, reason: body.reason, planned: cat.planned.includes(body.reason), operator: user.name, start: now, end: null });
} else if (path === '/andon/stop') {
  if (!active) return reply(409, { message: 'Tidak ada andon aktif di station ini.' });
  active.end = now;
  active.stoppedBy = user.name;
}

global.set('andonEvents', events);
msg.station = station;
return [null, msg];   // lanjut ke "ringkasan" untuk balasan + siaran dashboard

// Ringkasan andon + SIMULASI PRODUKSI. Dipanggil: tiap 1 detik (timer), setelah state/start/stop dari tablet,
// dan dari halaman admin (msg.admin). Simulasi: line menambah Assy Out setiap "interval" detik. Selama ADA andon aktif,
// line BERHENTI (qty tidak bertambah), seperti lapangan. Pengaturan diubah lewat halaman admin /andon-admin.
// ponytail: simulasi per detik cukup untuk demo. Ganti ke sumber data produksi asli (PLC/MES) bila ada.
const SEC_PER_MIN = 60;   // dummy cepat: ubah ke 5 supaya menit cepat berubah saat uji
const CATS = ['quality', 'logistic', 'equipment', 'process'];
const now = Date.now();

// ---------- pengaturan produksi (disimpan di memori Node-RED) ----------
const DEFAULT_CFG = { jph: 12, target: 92, interval: 300, auto: true, ct: 5, handover: 34, startHour: 7 };   // efisiensi TIDAK manual: dihitung dari downtime
const day = t => new Date(t + 7 * 3600e3).toISOString().slice(0, 10);   // tanggal WIB
const today = day(now);
let cfg = Object.assign({}, DEFAULT_CFG, global.get('andonCfg') || {});
const startOfDay = h => { const d = new Date(now + 7 * 3600e3); d.setUTCHours(0, 0, 0, 0); return d.getTime() - 7 * 3600e3 + h * 3600e3; };   // jam h WIB hari ini (ms)
let prod = global.get('andonProd') || { day: today, assyOut: 0, acc: 0, last: now, stopSec: 0, startAt: null };
if (prod.day !== today) prod = { day: today, assyOut: 0, acc: 0, last: now, stopSec: 0, startAt: null };   // ganti hari: mulai dari nol, start produksi kembali ke jam standar
if (!prod.startAt) prod.startAt = startOfDay(cfg.startHour);   // default: jam 07:00 WIB hari ini

// Riwayat awal supaya dashboard tidak kosong saat pameran (menit lalu, durasi menit, kategori, alasan, station).
if (!global.get('andonSeeded')) {
  global.set('andonSeeded', true);
  const M = 60e3;
  const ev0 = [
    [470, 3, 'equipment', 'Sensor error', 'MA-5-LH'], [395, 5, 'logistic', 'Part habis', 'MA-1-RH'],
    [330, 2, 'quality', 'Part NG / reject', 'MA-3-LH'], [262, 4, 'process', 'Cycle time terlalu lama', 'MA-8-RH'],
    [190, 3, 'logistic', 'Trolley kosong', 'MA-11-LH'], [128, 6, 'equipment', 'Tool rusak', 'MA-6-LH'],
    [95, 2, 'quality', 'Cacat visual', 'MA-3-RH'], [41, 3, 'process', 'Operator kurang', 'MA-12-LH'],
    [17, 2, 'quality', 'Torque tidak sesuai', 'MA-14-LH']
  ].map(([ago, dur, category, reason, station]) => ({ station, category, reason, operator: 'Operator Satu', start: now - ago * M, end: now - (ago - dur) * M }));
  global.set('andonEvents', [...(global.get('andonEvents') || []), ...ev0]);
  global.set('andonSessions', [
    ['Denny', 'MA-1-RH', 400, 330], ['Rijal', 'MA-16-LH', 330, 250], ['Idris', 'MA-9-RH', 250, 180],
    ['Fadillah', 'MA-11-LH', 200, 120], ['Rijal', 'MA-6-LH', 150, 70], ['Moh Wisnu', 'MA-5-LH', 55, null]
  ].map(([name, station, a, b]) => ({ name, station, start: now - a * M, end: b === null ? null : now - b * M })));
  prod.assyOut = 55;   // angka awal sama seperti dashboard lama
}

// ---------- aksi admin (dari /andon-admin): terapkan dulu, lalu hitung ulang ----------
if (msg.admin) {
  const a = msg.admin, n = Number(a.value);
  const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
  if (a.type === 'set') {
    const next = Object.assign({}, cfg);
    for (const k of ['jph', 'target', 'ct', 'handover']) if (a[k] !== undefined && Number.isFinite(Number(a[k]))) next[k] = clamp(Math.round(Number(a[k])), 0, 100000);
    if (a.interval !== undefined && Number.isFinite(Number(a.interval))) next.interval = clamp(Math.round(Number(a.interval)), 1, 86400);
    if (a.startHour !== undefined && Number.isFinite(Number(a.startHour))) { next.startHour = clamp(Number(a.startHour), 0, 23.99); if (!a.keepStart) prod.startAt = startOfDay(next.startHour); }
    if (a.auto !== undefined) next.auto = !!a.auto;
    cfg = next; global.set('andonCfg', cfg);
  } else if (a.type === 'add') {   // tambah qty manual (boleh negatif untuk koreksi)
    prod.assyOut = Math.max(0, prod.assyOut + Math.round(Number.isFinite(n) ? n : 1));
  } else if (a.type === 'startNow') {   // mulai produksi sekarang (efisiensi dihitung dari titik ini)
    prod.startAt = now; prod.acc = 0;
  } else if (a.type === 'resetQty') {
    prod.assyOut = 0; prod.acc = 0; prod.stopSec = 0;
  } else if (a.type === 'resetDowntime') {   // hapus riwayat andon (termasuk yang aktif) -> line jalan lagi
    global.set('andonEvents', []);
  } else if (a.type === 'clearActive') {      // akhiri semua andon yang sedang aktif (riwayat tetap)
    const t = Date.now();
    global.set('andonEvents', (global.get('andonEvents') || []).map(e => (e.end ? e : Object.assign({}, e, { end: t, stoppedBy: 'admin' }))));
  } else if (a.type === 'defaults') {
    cfg = Object.assign({}, DEFAULT_CFG); global.set('andonCfg', cfg); prod.startAt = startOfDay(cfg.startHour);
  }
}

const events = global.get('andonEvents') || [];
const live = events.filter(e => !e.end);   // andon yang sedang aktif

// ---------- simulasi: tambah qty tiap interval, kecuali sedang ada andon ----------
const dt0 = Math.min(Math.max((now - prod.last) / 1000, 0), 30);   // batasi loncatan waktu (mis. Node-RED sempat mati)
prod.last = now;
const stopped = live.length > 0;
if (msg.admin) { /* aksi admin tidak memajukan waktu simulasi */ }
else if (stopped) prod.stopSec += dt0;
else if (cfg.auto && cfg.interval > 0) {
  prod.acc += dt0;
  while (prod.acc >= cfg.interval) { prod.acc -= cfg.interval; prod.assyOut++; }
}
global.set('andonProd', prod);

// ---------- efisiensi OTOMATIS dari downtime ----------
// 100% = dari start produksi sampai sekarang tidak ada downtime unplanned. Downtime planned dikeluarkan dari waktu yang dihitung.
const merge = iv => { const a = iv.filter(x => x[1] > x[0]).sort((p, q) => p[0] - q[0]); const o = []; for (const x of a) { const l = o[o.length - 1]; if (l && x[0] <= l[1]) l[1] = Math.max(l[1], x[1]); else o.push([x[0], x[1]]); } return o; };
const clip = (e, lo, hi) => [Math.max(e.start, lo), Math.min(e.end || now, hi)];
const len = iv => iv.reduce((n, x) => n + (x[1] - x[0]), 0);
const subtract = (iv, cut) => { const o = []; for (const x of iv) { let s = x[0]; for (const c of cut) { if (c[1] <= s || c[0] >= x[1]) continue; if (c[0] > s) o.push([s, c[0]]); s = Math.max(s, c[1]); } if (s < x[1]) o.push([s, x[1]]); } return o; };
const calcEff = () => {
  const lo = Math.min(prod.startAt, now), hi = now;
  const range = hi - lo;
  if (range < 1000) return { eff: 100, rangeSec: 0, plannedSec: 0, unplannedSec: 0 };
  const plannedIv = merge(events.filter(e => e.planned).map(e => clip(e, lo, hi)));
  const unplannedIv = subtract(merge(events.filter(e => !e.planned).map(e => clip(e, lo, hi))), plannedIv);
  const planned = len(plannedIv), unplanned = len(unplannedIv), base = range - planned;
  const eff = base > 0 ? Math.max(0, Math.min(100, (1 - unplanned / base) * 100)) : 100;
  return { eff: Math.round(eff * 10) / 10, rangeSec: Math.round(range / 1000), plannedSec: Math.round(planned / 1000), unplannedSec: Math.round(unplanned / 1000) };
};
const E = calcEff();

// ---------- ringkasan downtime per kategori (hari ini WIB) ----------
const dt = {}, secs = {}, running = {};
for (const c of CATS) { dt[c] = { active: false, count: 0, minutes: 0, station: '-' }; secs[c] = 0; running[c] = []; }
for (const e of events) {
  if (e.end && day(e.start) !== today) continue;   // selesai di hari lain: abaikan (andon aktif lintas hari tetap dihitung)
  dt[e.category].count++;
  secs[e.category] += ((e.end || now) - e.start) / 1000;   // aktif: lama berjalan ikut dihitung
  if (!e.end) running[e.category].push(e);
}
for (const c of CATS) dt[c].plannedActive = running[c].some(e => e.planned);
for (const c of CATS) {
  dt[c].minutes = Math.floor(secs[c] / SEC_PER_MIN);
  const r = running[c].sort((a, b) => a.start - b.start);
  if (r.length) {
    dt[c].active = true;
    dt[c].station = r[0].station + (r.length > 1 ? ' +' + (r.length - 1) : '');
  }
}

// events + workers = data mentah untuk halaman /line (analitik dihitung di frontend).
const cut = now - 24 * 3600e3;
const evOut = events.filter(e => (e.end || now) > cut).map(({ station, category, reason, planned, operator, start, end }) => ({ station, category, reason, planned: !!planned, operator, start, end }));
const workers = (global.get('andonSessions') || []).slice(-40).map(({ name, station, start, end }) => ({ name, station, start, end }));
const dashboard = {
  target: cfg.target, assyOut: prod.assyOut, efficiency: E.eff, jph: cfg.jph, ct: cfg.ct, handover: cfg.handover,
  startAt: prod.startAt, eff: E,
  running: !stopped, intervalSec: cfg.interval, auto: cfg.auto,
  downtime: dt, now, events: evOut, workers, ts: new Date(now).toISOString()
};
const toDashboard = { payload: dashboard };   // tanpa req/res: disiarkan ke semua dashboard

// status untuk halaman admin
const adminState = {
  cfg, assyOut: prod.assyOut, stopped, stopSec: Math.round(prod.stopSec || 0), startAt: prod.startAt, eff: E,
  nextIn: stopped || !cfg.auto ? null : Math.max(0, Math.ceil(cfg.interval - (prod.acc || 0))),
  active: live.map(e => ({ station: e.station, category: e.category, reason: e.reason, planned: !!e.planned, since: e.start })),
  eventsToday: events.filter(e => day(e.start) === today).length, now
};

if (msg.admin) { msg.statusCode = 200; msg.payload = adminState; return [msg, toDashboard]; }   // balasan HTTP admin + siaran
if (!msg.res) return [null, toDashboard];                                                     // dari timer

const a = events.find(e => !e.end && e.station === msg.station);
msg.payload = {
  active: a ? { category: a.category, reason: a.reason, planned: !!a.planned, start: a.start, operator: a.operator } : null,
  downtime: dt,
  now
};
return [msg, toDashboard];

// Halaman admin Andon (HTML sederhana, tanpa library). Dilayani di GET /andon-admin.
// Memanggil: GET /andon-admin/state, POST /andon-admin/act. Hanya untuk jaringan lokal/pameran.
// ponytail: tanpa login. Tambahkan httpNodeAuth/adminAuth di settings.js kalau Node-RED dibuka ke jaringan yang tidak dipercaya.
msg.headers = { 'content-type': 'text/html; charset=utf-8' };
msg.statusCode = 200;
msg.payload = `<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Andon Admin</title>
<style>
