body{margin:0;font:16px/1.45 system-ui,Segoe UI,Arial,sans-serif;background:#0a1220;color:#e2e8f0;padding:20px;max-width:1100px;margin:auto}
h1{margin:0 0 4px;font-size:26px}h2{margin:0 0 12px;font-size:15px;letter-spacing:.08em;text-transform:uppercase;color:#94a3b8}
.sub{color:#94a3b8;margin-bottom:18px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:16px}
.card{background:#111c2e;border:1px solid #1e2d45;border-radius:14px;padding:18px}
.big{font-size:54px;font-weight:800;line-height:1;font-variant-numeric:tabular-nums}
.st{display:inline-flex;align-items:center;gap:8px;border-radius:999px;padding:5px 14px;font-weight:700;font-size:14px}
.run{background:#34d39926;color:#34d399}.stop{background:#f8717126;color:#f87171;animation:p 1s infinite alternate}
@keyframes p{to{opacity:.55}}
label{display:block;font-size:13px;color:#94a3b8;margin:12px 0 4px}
input[type=number]{width:100%;background:#0a1220;border:1px solid #2a3b57;color:#e2e8f0;border-radius:10px;padding:10px 12px;font-size:17px}
input:focus{outline:2px solid #2dd4bf;border-color:transparent}
.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
button{border:0;border-radius:10px;padding:11px 16px;font-size:15px;font-weight:700;cursor:pointer;background:#2dd4bf;color:#042;transition:transform .08s}
button:active{transform:scale(.96)}button.sec{background:#1e2d45;color:#e2e8f0}button.red{background:#f87171;color:#300}button.amb{background:#fbbf24;color:#320}
.msg{min-height:22px;margin-top:10px;font-size:14px;color:#94a3b8}.ok{color:#34d399}.er{color:#f87171}
ul{margin:8px 0 0;padding-left:18px}.kv{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #1e2d45}
.kv:last-child{border:0}.sw{display:flex;align-items:center;gap:10px;margin-top:12px}
</style></head><body>
<h1>Andon Admin</h1><div class="sub">Atur produksi dummy untuk dashboard dan tablet. Perubahan langsung dipakai dashboard.</div>
<div class="grid">
 <div class="card"><h2>Status produksi</h2>
  <div class="big" id="qty">-</div><div style="color:#94a3b8">Assy Out hari ini</div>
  <div style="margin:12px 0"><span id="badge" class="st run">-</span></div>
