// Rute admin andon: GET /andon-admin/state dan POST /andon-admin/act. Memvalidasi aksi, lalu meneruskan ke "ringkasan andon".
// ponytail: tanpa login. Tambahkan httpNodeAuth di settings.js kalau Node-RED dibuka ke jaringan yang tidak dipercaya.
const act = msg.req.params.act;
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const bad = (code, message) => { msg.statusCode = code; msg.payload = { message }; return [msg, null]; };

if (msg.req.method === 'GET' && act === 'state') { msg.admin = { type: 'state' }; return [null, msg]; }
if (msg.req.method === 'POST' && act === 'act') {
  const T = ['set', 'add', 'startNow', 'resetQty', 'resetDowntime', 'clearActive', 'defaults'];
  if (!T.includes(body.type)) return bad(400, 'Aksi tidak dikenal.');
  if (body.type === 'add' && !Number.isFinite(Number(body.value))) return bad(400, 'Jumlah harus angka.');
  if (body.type === 'set') {
    for (const k of ['jph', 'target', 'interval', 'ct', 'handover'])
      if (body[k] !== undefined && (!Number.isFinite(Number(body[k])) || Number(body[k]) < 0)) return bad(400, k + ' harus angka >= 0.');
    if (body.interval !== undefined && Number(body.interval) < 1) return bad(400, 'Interval minimal 1 detik.');
    if (body.startHour !== undefined && (!Number.isFinite(Number(body.startHour)) || Number(body.startHour) < 0 || Number(body.startHour) >= 24)) return bad(400, 'Jam mulai harus 0 sampai 23,99.');
  }
  msg.admin = body;
  return [null, msg];
}
return bad(404, 'Rute admin tidak dikenal.');

// BACKEND DUMMY tablet QC + siaran ke dashboard (/ws/qc). State di memori global Node-RED (hilang saat restart).
// Terpisah dari andon. Satu function untuk semua: HTTP /qc/:action dan timer 1 detik.
// ponytail: data dummy dalam kode. Ganti ke database/API asli kalau sudah ada.
// Station: daftar yang sama dengan dashboard kualitas. Station tablet dipilih di Setting.
const DASH_STATIONS = [['FIT-FINISH', 'Fit Finish'], ['PRE-DYNO', 'Pre Dyno'], ['DYNO', 'Dyno'], ['HLA', 'HLA'], ['RUNNING', 'Running'], ['OFFLINE', 'Offline'], ['FINAL-INSPECTION', 'Final Inspection']];
const stationName = code => (DASH_STATIONS.find(x => x[0] === code) || [])[1];
const DEFAULT_STATION = 'FIT-FINISH';
// Akun operator: pilih email dari dropdown, password sama untuk semua (dummy). ponytail: ganti ke login/direktori asli nanti.
const PASSWORD = 'qc123';
const ACCOUNTS = [
  ['qc1@dummy.local', 'Operator QC'], ['wisnu@dummy.local', 'Moh Wisnu Aji Saputro'], ['fadillah@dummy.local', 'Fadillah'],
  ['denny@dummy.local', 'Denny'], ['rijal@dummy.local', 'Rijal'], ['idris@dummy.local', 'Idris']
].map(([email, name]) => ({ email, name }));
const OPERATORS = ACCOUNTS.map(a => a.name);
const SESSION_MS = 15 * 60e3;   // sesi diam > 15 menit dilepas otomatis
const M = 60e3;

// Aturan VIN (posisi mulai dari 1): karakter 6-7 = model (M1 One, M2 Cervo, M3 N3), karakter 10 = warna (A putih, B biru, C merah, lainnya hitam).
// Contoh: ALVA0M1XXAXX -> Alva One Putih
const MODELS = { M1: 'Alva One', M2: 'Alva Cervo', M3: 'Alva N3' };
const COLORS = { A: 'Putih', B: 'Biru', C: 'Merah' };
const parseVin = vin => {
  if (!/^[A-Z0-9]{10,20}$/.test(vin)) return { error: ['VIN_INVALID', 'Format VIN tidak valid. Minimal 10 karakter huruf/angka.'] };
  const code = vin.slice(5, 7);
  if (!MODELS[code]) return { error: ['MODEL_UNKNOWN', `Model tidak dikenali (karakter 6-7 = "${code}"). Harus M1, M2, atau M3.`] };
  return { unit: { vin, modelCode: code, model: MODELS[code], color: COLORS[vin[9]] || 'Hitam' } };
};

const ALL = ['Misassembled', 'Missing Part', 'Over cutting', 'Peel-Off', 'Poor Repair', 'Scratch', 'Stain', 'Tear', 'Touch Mark', 'Wrong Position', 'Wrong specification'];
const GEN = ['Misassembled', 'Missing Part', 'Scratch', 'Stain', 'Touch Mark', 'Wrong Position'];
// [id, nama, berkas foto di tablet QC/public/parts/<x>.png (kosong = ikon), defect khusus + umum]
const PARTS = [
  ['p1', 'Body Cover RH', 'body-cover-rh', ['Gap-Above', ...ALL]],
  ['p2', 'Body Cover LH', 'body-cover-lh', ['Gap-Above', ...ALL]],
  ['p3', 'Rear Mud Guard', 'rear-mud-guard', ['Misalignment', ...GEN]],
  ['p4', 'Speedometer', 'speedometer', ['Gate Blush', ...GEN]],
  ['p5', 'Steering Cover Rear', 'steering-cover-rear', ['Touching', ...GEN]],
  ['p6', 'Rear Handle RH', 'rear-handle-rh', ['Damage', ...GEN]],
  ['p7', 'Keyless SET', 'keyless-set', ['Gap-Above', 'Flush', ...GEN]],
  ['p8', 'Foot Step LH', 'foot-step-lh', ['Touching', ...GEN]],
  ['p9', 'Foot Step RH', 'foot-step-rh', ['Abnormal Function', ...GEN]],
  ['p10', 'Horn', '', ['Abnormal Sound', ...GEN]]
].map(([id, name, image, d], i) => ({ id, no: i + 1, name, image, defects: [...new Set(d)].sort() }));
const PN = Object.fromEntries(PARTS.map(p => [p.id, p.name]));

// Data awal supaya dashboard tidak kosong: 70 inspeksi 9 jam terakhir (30 NG, 40 GOOD).
const fresh = now => {
  const w = [['p3', 'Misalignment', 14], ['p4', 'Gate Blush', 11], ['p5', 'Touching', 9], ['p1', 'Gap-Above', 8], ['p6', 'Damage', 7],
    ['p2', 'Gap-Above', 6], ['p7', 'Gap-Above', 5], ['p8', 'Touching', 4], ['p7', 'Flush', 3], ['p9', 'Abnormal Function', 2]];
  const flat = [];
  w.forEach(([partId, defect, c]) => { for (let i = 0; i < c; i++) flat.push({ partId, defect }); });
  const results = [];
  let k = 0;
  for (let i = 0; i < 70; i++) {
    const bad = i % 7 < 3;
    const ng = bad ? flat.filter((_, j) => j % 30 === k) : [];
    if (bad) k++;
    const vin = 'HIST0M' + (i % 3 + 1) + 'XX' + 'ABCD'[i % 4] + String(i).padStart(3, '0');
    const u = parseVin(vin).unit;
    results.push({ id: 's' + i, station: 'FIT-FINISH', vin, model: u.model, color: u.color, at: now - (i + 1) * 8 * M,
      operator: OPERATORS[i % OPERATORS.length], status: bad ? 'NOT_GOOD' : 'GOOD', ng, seconds: 40 + (i * 7) % 50 });
  }
  return {
    // VIN demo untuk mencoba penolakan: selesai (GOOD), menunggu repair, dan sedang dipakai tablet lain
    units: { DEMO0M1XXA001: 'finalized', DEMO0M3XXC002: 'repair' },
    sessions: [{ vin: 'DEMO0M2XXB003', deviceId: 'seed', operator: OPERATORS[1], station: 'FIT-FINISH', start: now, sticky: true }],
    results
  };
};


// ---------- Quality dashboard (historis, dummy) ----------
// Bentuk sama dengan halaman asli: per station -> {totalUnit,target,qtyProduct,totalDefect,dpu,okRatio,chart}. Angka dummy deterministik.
const PERIODS = ['lastMonth', 'thisMonth', 'lastWeek', 'thisWeek', 'yesterday', 'today'];
const KEYS = { M1: 'ONE', M2: 'CERVO', M3: 'N3' };
const rnd = (a, b) => { const x = Math.sin(a * 127.1 + b * 311.7) * 43758.5453; return x - Math.floor(x); };
const r1 = (v, d) => Number(v.toFixed(d));
const dashboard = (dateStr) => {
  const seedDay = [...dateStr].reduce((n, c) => n + c.charCodeAt(0), 0);
  const stations = {};
  DASH_STATIONS.forEach(([code], si) => {
    const qty = {}, def = {}, dpu = {}, ok = {}, chart = { dpu: {}, okRatio: {} };
    PERIODS.forEach(per => { chart.dpu[per] = {}; chart.okRatio[per] = {}; });
    Object.values(KEYS).forEach((k, mi) => {
      const base = 0.55 + 0.35 * rnd(si + 1, mi + 7);          // DPU dasar per station/model
      const targetDpu = mi === 2 ? 1.4 : 1.2 + 0.2 * mi;
      const targetOk = mi === 2 ? 5 : 8 + 2 * mi;
      PERIODS.forEach((per, pi) => {
        let act = r1(Math.max(0.05, base * (1.15 - pi * 0.1) * (0.9 + 0.25 * rnd(seedDay + pi, si * 3 + mi))), 2);
        if (mi < 2 && pi < 4 && rnd(si + 9, mi + pi) > 0.45) act = r1(act * (2.5 + 3 * rnd(si + pi, mi + 4)), 2);   // ONE/CERVO kadang melewati target (batang merah)
        let okv = r1(Math.min(99, 40 + 30 * rnd(si + 2, mi + 3) + pi * 3 + 5 * rnd(seedDay, pi + mi)), 1);
        if (mi < 2 && pi < 3 && rnd(si + 4, mi + pi + 2) > 0.5) okv = r1(targetOk * (0.4 + 0.5 * rnd(si, pi + mi)), 1);   // sesekali di bawah target OK ratio
        chart.dpu[per][k] = { actualDpu: act, targetDpu };
        chart.okRatio[per][k] = { totalOkRatio: okv, targetOkRatio: targetOk };
      });
      const q = Math.round(40 + 70 * rnd(si + 5, mi + 11) * (mi === 2 ? 1 : 0.6));
      qty[k] = q;
      dpu[k] = chart.dpu.today[k];
      ok[k] = chart.okRatio.today[k];
      def[k] = Math.round(q * dpu[k].actualDpu);
    });
    const total = Object.values(qty).reduce((a, b) => a + b, 0);
    stations[code] = { totalUnit: total, target: Math.round(total * 0.97), qtyProduct: qty, totalDefect: def, dpu, okRatio: ok, chart };
  });
  return { stations, list: DASH_STATIONS.map(([code, name]) => ({ code, name })) };
};

const now = Date.now();
let S = global.get('qc');
if (!S) S = fresh(now);
S.sessions = S.sessions.filter(s => s.sticky || now - s.start < SESSION_MS);

const summary = (station = DEFAULT_STATION) => {
  const rs = S.results.filter(r => r.at >= now - 24 * 3600e3 && (r.station || 'FIT-FINISH') === station);
  const good = rs.filter(r => r.status === 'GOOD').length;
  const cnt = new Map();
  for (const r of rs) for (const g of r.ng) { const k = g.partId + '|' + g.defect; cnt.set(k, (cnt.get(k) || 0) + 1); }
  const top = [...cnt].map(([k, count]) => { const [partId, defect] = k.split('|'); return { partId, part: PN[partId], defect, count }; })
    .sort((a, b) => b.count - a.count || a.part.localeCompare(b.part)).slice(0, 10);
  return {
    station, stationName: stationName(station),
    totals: { inspected: rs.length, good, notGood: rs.length - good, okRate: rs.length ? Math.round(good / rs.length * 1000) / 10 : 0 },
    top,
    byPart: PARTS.map(p => ({ partId: p.id, part: p.name, count: rs.reduce((n, r) => n + r.ng.filter(g => g.partId === p.id).length, 0) })),
    byModel: Object.values(MODELS).map(m => { const x = rs.filter(r => r.model === m); return { model: m, inspected: x.length, notGood: x.filter(r => r.status === 'NOT_GOOD').length }; }),
    active: S.sessions.filter(s => (s.station || 'FIT-FINISH') === station).map(s => ({ vin: s.vin, operator: s.operator, since: s.start })),
    recent: rs.slice(0, 10).map(r => ({ vin: r.vin, model: r.model, color: r.color, at: r.at, status: r.status, ng: r.ng.length, operator: r.operator })),
    now, ts: new Date(now).toISOString()
  };
};
const broadcast = () => ({ payload: summary() });

// timer: hanya siaran ke dashboard
if (!msg.req) { global.set('qc', S); return [null, broadcast()]; }

const action = msg.req.params.action;
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const reply = (code, payload, bc) => { msg.statusCode = code; msg.payload = payload; global.set('qc', S); return [msg, bc ? broadcast() : null]; };
const fail = (code, errCode, message) => reply(code, { code: errCode, message }, false);

const qStation = code => (DASH_STATIONS.some(x => x[0] === code) ? code : DEFAULT_STATION);
if (action === 'catalog') return reply(200, { stations: DASH_STATIONS.map(([code, name]) => ({ code, name })), accounts: ACCOUNTS, parts: PARTS }, false);
if (action === 'state') return reply(200, summary(qStation(String((msg.req.query && msg.req.query.station) || ''))), false);
if (action === 'dashboard') {
  const q = String((msg.req.query && msg.req.query.date) || '');
  const d = /^\d{4}-\d{2}-\d{2}$/.test(q) && !isNaN(Date.parse(q)) ? q : new Date(now + 7 * 3600e3).toISOString().slice(0, 10);
  const dash = dashboard(d);
  // FIT-FINISH hari ini = inspeksi nyata dari tablet QC (S.results), supaya tablet dan dashboard nyambung.
  const day = x => new Date(x + 7 * 3600e3).toISOString().slice(0, 10);
  const ff = dash.stations['FIT-FINISH'];
  const rs = S.results.filter(r => day(r.at) === d && (r.station || 'FIT-FINISH') === 'FIT-FINISH');
  if (rs.length) {
    ['ONE', 'CERVO', 'N3'].forEach(k => {
      const m = rs.filter(r => (Object.values(MODELS).includes(r.model) ? { 'Alva One': 'ONE', 'Alva Cervo': 'CERVO', 'Alva N3': 'N3' }[r.model] : '') === k);
      const q = m.length, nd = m.reduce((n, r) => n + r.ng.length, 0), good = m.filter(r => r.status === 'GOOD').length;
      ff.qtyProduct[k] = q; ff.totalDefect[k] = nd;
      const a = q ? Math.round(nd / q * 100) / 100 : 0, o = q ? Math.round(good / q * 1000) / 10 : 0;
      ff.dpu[k] = { actualDpu: a, targetDpu: ff.dpu[k].targetDpu }; ff.okRatio[k] = { totalOkRatio: o, targetOkRatio: ff.okRatio[k].targetOkRatio };
      ff.chart.dpu.today[k] = ff.dpu[k]; ff.chart.okRatio.today[k] = ff.okRatio[k];
    });
    ff.totalUnit = rs.length; ff.target = Math.round(rs.length * 0.97);
  }
  const KMAP = { 'Alva One': 'ONE', 'Alva Cervo': 'CERVO', 'Alva N3': 'N3' };
  for (const [code] of DASH_STATIONS) {
    if (code === 'FIT-FINISH') continue;
    const rr = S.results.filter(r => day(r.at) === d && r.station === code);
    if (!rr.length) continue;
    const sx = dash.stations[code];
    ['ONE', 'CERVO', 'N3'].forEach(k => {
      const m = rr.filter(r => KMAP[r.model] === k);
      const q = m.length, nd = m.reduce((n, r) => n + r.ng.length, 0), good = m.filter(r => r.status === 'GOOD').length;
      sx.qtyProduct[k] = q; sx.totalDefect[k] = nd;
      const a = q ? Math.round(nd / q * 100) / 100 : 0, o = q ? Math.round(good / q * 1000) / 10 : 0;
      sx.dpu[k] = { actualDpu: a, targetDpu: sx.dpu[k].targetDpu }; sx.okRatio[k] = { totalOkRatio: o, targetOkRatio: sx.okRatio[k].targetOkRatio };
      sx.chart.dpu.today[k] = sx.dpu[k]; sx.chart.okRatio.today[k] = sx.okRatio[k];
    });
    sx.totalUnit = rr.length; sx.target = Math.round(rr.length * 0.97);
  }
  return reply(200, { date: d, ...dash, note: 'Data dummy deterministik. Target = referensi bisnis saat ini.' }, false);
}
if (action === 'reset') { S = fresh(now); return reply(200, { ok: true }, true); }

const vin = typeof body.vin === 'string' ? body.vin.trim().toUpperCase() : '';
const dev = typeof body.deviceId === 'string' ? body.deviceId.slice(0, 64) : '';
const operator = OPERATORS.includes(body.operator) ? body.operator : null;
const bStation = DASH_STATIONS.some(x => x[0] === body.station) ? body.station : null;

if (action === 'login') {
  const acc = ACCOUNTS.find(a => a.email === String(body.email || '').trim().toLowerCase());
  if (!acc || body.password !== PASSWORD) return fail(401, 'LOGIN_FAILED', 'Email atau password salah.');
  return reply(200, { name: acc.name, email: acc.email }, false);
}

if (action === 'scan') {
  if (!dev) return fail(400, 'DEVICE_INVALID', 'ID perangkat tidak ada.');
  if (!operator) return fail(400, 'OPERATOR_INVALID', 'Login operator terlebih dahulu.');
  if (!bStation) return fail(400, 'STATION_INVALID', 'Station belum diatur. Buka Setting.');
  const p = parseVin(vin);
  if (p.error) return fail(400, p.error[0], p.error[1]);
  if (S.units[vin] === 'finalized') return fail(409, 'ALREADY_FINALIZED', 'VIN ini sudah selesai diperiksa (OK).');
  if (S.units[vin] === 'repair') return fail(409, 'REPAIR_REQUIRED', 'VIN ini punya NG dan menunggu repair.');
  const act = S.sessions.find(s => s.vin === vin);
  if (act && act.deviceId !== dev) return fail(409, 'SESSION_ACTIVE', 'Ada sesi aktif untuk VIN ini di tablet lain.');
  S.sessions = S.sessions.filter(s => s.deviceId !== dev);   // satu tablet satu sesi
  S.sessions.push({ vin, deviceId: dev, operator, station: bStation, start: now });
  return reply(200, { unit: p.unit }, true);
}

if (action === 'cancel') {
  S.sessions = S.sessions.filter(s => !(s.vin === vin && s.deviceId === dev));
  return reply(200, { ok: true }, true);
}

if (action === 'finish') {
  const ses = S.sessions.find(s => s.vin === vin && s.deviceId === dev);
  if (!ses) return fail(409, 'NO_SESSION', 'Sesi inspeksi tidak ditemukan atau sudah berakhir. Scan VIN lagi.');
  if (!Array.isArray(body.ng) || body.ng.length > 60) return fail(400, 'NG_INVALID', 'Data NG tidak valid.');
  const seen = new Set();
  const ng = [];
  for (const g of body.ng) {
    const part = g && typeof g.partId === 'string' ? PARTS.find(p => p.id === g.partId) : null;
    if (!part || typeof g.defect !== 'string' || !part.defects.includes(g.defect)) return fail(400, 'NG_INVALID', 'Defect tidak dikenal untuk part tersebut.');
    const k = g.partId + '|' + g.defect;
    if (!seen.has(k)) { seen.add(k); ng.push({ partId: g.partId, defect: g.defect }); }
  }
  const u = parseVin(vin).unit;
  const status = ng.length ? 'NOT_GOOD' : 'GOOD';   // tanpa NG = OK
  S.results.unshift({ id: now.toString(36), station: ses.station, vin, model: u.model, color: u.color, at: now, operator: ses.operator, status, ng, seconds: Math.round((now - ses.start) / 1000) });
  S.results = S.results.slice(0, 300);
  S.units[vin] = status === 'GOOD' ? 'finalized' : 'repair';
  S.sessions = S.sessions.filter(s => s !== ses);
  return reply(200, { vin, status, ng }, true);
}

return fail(404, 'UNKNOWN_ACTION', 'Aksi tidak dikenal.');
